/** A circuit in code (docs/eda-authoring.md): check it, route it and make its files with no editor open. fileId is the Drive id of its schematic (.sch.tsx, .sch.py, .sch.rs) or of its board (.pcb.tsx, .pcb.py, .pcb.rs). */
export class Eda {
  constructor(private readonly t: Transport) {}
  /** Electrical rule check of the schematic: each violation with its rule, severity, pins, and the code elements (file, line) that declare them. CommandAGI's rules over the netlist, not KiCad's ERC. `warnings: false` lists the errors only. */
  erc(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("sch_erc", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Design rule check of the board: each violation with the code elements it is about. A rule given in opts (clearance, trackWidth …) replaces the board's. */
  drc(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_drc", { ...prune({ fileId: fileId }), ...opts });
  }
  /** The circuit's parts, pins and nets, as the schematic states them. */
  netlist(fileId: string): Promise<unknown> {
    return this.t.call("sch_netlist", prune({ fileId: fileId }));
  }
  /** The manufacturing files of the board (Gerber layers, drill files, bill of materials, pick-and-place); `omitted` names what a file leaves out. */
  fabricate(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_fabricate", { ...prune({ fileId: fileId }), ...opts });
  }
  /** The board as a 3D model (format: step or obj). The STEP is an assembly: the board with its holes, each part's own model where its footprint names one in the drive, else a bounding body that says so. */
  model3d(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_model3d", { ...prune({ fileId: fileId }), ...opts });
  }
  /** The board as a KiCad project beside it: <stem>.kicad_pcb (every technical layer declared, so KiCad plots mask and paste), a schematic KiCad's parity check compares with the board (no-connect flags on pins left open), <stem>.kicad_pro (the net classes) and fp-lib-table. `schematic: false` writes the board and project only. */
  exportKicad(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_export_kicad", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Lay out the board by its constraints (<netclass>, <group>, <keepout> …): place the parts with no place, route every net with its class's rules, check, repair, score; again until clean or the budget (budgetMinutes) is spent. Writes the placements and copper into the board's code and says each attempt. A board or a budget too large to lay out in place runs as a job, which this follows to its end (pcb_layout_status). */
  layout(fileId: string, opts: Args = {}): Promise<unknown> {
    return followJob(
      this.t,
      this.t.call("pcb_layout", { ...prune({ fileId: fileId }), ...opts }),
      "pcb_layout_status",
    );
  }
  /** A layout job: its state while it runs; when it is done, what layout answers, with the board files written (or why not). */
  layoutStatus(job: string): Promise<unknown> {
    return this.t.call("pcb_layout_status", prune({ job: job }));
  }
  /** Every term of the board's layout objective (unrouted, DRC errors, overlaps, keep-outs, regions, wire length, vias …) with its weight, the weighted total, and each layout check's verdict. */
  layoutScore(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_layout_score", { ...prune({ fileId: fileId }), ...opts });
  }
  /** The layout checks' findings (placed, routed, DRC with the net classes, courtyards, keep-outs, regions, near, width, length, vias, skew, heat, octolinear, detour, return path): what, where, on which part or net. */
  checkLayout(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_check_layout", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Set or remove one constraint of the board ({ constraint: "netclass", name, attributes: { nets, width, … } }); written into the board's code as its element. */
  constrain(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_constrain", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Place the parts of one group ({ group } or { parts }) by the constraint model; the copper of their nets is ripped up, to be routed again. */
  placeGroup(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_place_group", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Route what is open of the nets named ({ nets }; all when none) with their net classes' rules, from the copper they have, on the copper layers given ({ layers }; default the two outer layers, through vias), and write the traces into the board's code. { ripUp: true } removes the nets' copper first. The result names each connection left unrouted; `complete` is false while one is. */
  routeNets(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_route_nets", { ...prune({ fileId: fileId }), ...opts });
  }
  /** Remove the tracks and vias of the nets named ({ nets }). */
  ripUp(fileId: string, opts: Args = {}): Promise<unknown> {
    return this.t.call("pcb_rip_up", { ...prune({ fileId: fileId }), ...opts });
  }
}

